package dev.omnidisplay;
import java.util.UUID;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.core.HolderLookup;
import net.minecraft.world.item.ItemStack;
public final class CabinSettings {
 public net.minecraft.core.BlockPos[] clickOrigins=new net.minecraft.core.BlockPos[0];
 public net.minecraft.core.BlockPos radarLink,radarController;
 public boolean mouseLock=true,mouseWireless=true;public ItemStack mouseFirst=ItemStack.EMPTY,mouseSecond=ItemStack.EMPTY;
 public net.minecraft.world.phys.Vec3 hudCenter; // Relative to origin, follows plot relocation.
 public int hudMask=63,seamOpacity=5;
 public int hudBrightness=150,highlightOpacity=100,hudScale=500,hudColor=0x78FFFF;
 public net.minecraft.core.BlockPos origin=null,faultOrigin=null;public int faultEvent=-1;
 public java.util.List<HighlightRegion> highlights=new java.util.ArrayList<>();
 public int highlightAt(java.util.UUID body,net.minecraft.core.BlockPos pos,net.minecraft.core.BlockPos plotCenter,boolean owner){for(int i=highlights.size()-1;i>=0;i--){var h=highlights.get(i);if(h.body()==null){if(owner&&origin!=null&&h.contains(pos.subtract(origin)))return h.opacity();}else if(body.equals(h.body())&&(h.kind().equals("ship")||(h.kind().equals("blocks")&&h.matches(pos.subtract(plotCenter)))))return h.opacity();}return -1;}
 public int blockOpacity(java.util.UUID id,net.minecraft.core.BlockPos local){for(int i=highlights.size()-1;i>=0;i--){var h=highlights.get(i);if(id.equals(h.body())&&(h.kind().equals("ship")||(h.kind().equals("blocks")&&h.matches(local))))return h.opacity();}return -1;}
 public int structureOpacity(java.util.UUID id,String kind){for(int i=highlights.size()-1;i>=0;i--){var h=highlights.get(i);if(id.equals(h.body())&&kind.equals(h.kind()))return h.opacity();}return -1;}
 public int override(net.minecraft.core.BlockPos p){if(origin==null)return -1;var relative=p.subtract(origin);for(int i=highlights.size()-1;i>=0;i--)if(highlights.get(i).contains(relative))return highlights.get(i).opacity();return -1;}
 public void moveOrigin(net.minecraft.core.BlockPos next){if(origin!=null&&!origin.equals(next)){var offset=origin.subtract(next);hudCenter=HudCenterData.move(hudCenter,offset);if(radarLink!=null)radarLink=radarLink.offset(offset);if(radarController!=null)radarController=radarController.offset(offset);for(int i=0;i<highlights.size();i++)highlights.set(i,highlights.get(i).move(offset));}origin=next;}
 public void fault(long now,net.minecraft.core.BlockPos pos){
  if(!animating(now)){faultOrigin=null;faultEvent=-1;waveBase=power;waveTimes=new long[0];waveTargets=new boolean[0];clickOrigins=new net.minecraft.core.BlockPos[0];waveHeading=heading;}
  int n=waveTimes.length;if(n>=64){waveBase=power;waveTimes=new long[0];waveTargets=new boolean[0];clickOrigins=new net.minecraft.core.BlockPos[0];n=0;}
  waveTimes=java.util.Arrays.copyOf(waveTimes,n+1);waveTargets=java.util.Arrays.copyOf(waveTargets,n+1);waveTimes[n]=now;waveTargets[n]=false;
  clickOrigins=java.util.Arrays.copyOf(clickOrigins,n+1);
  power=false;faultOrigin=pos.immutable();faultEvent=n;
 }
 public int heading=0,waveHeading=0;public boolean waveBase;public long[] waveTimes=new long[0];public boolean[] waveTargets=new boolean[0];
 public boolean animating(double now){return waveTimes.length>0&&now-waveTimes[waveTimes.length-1]<dev.omnidisplay.region.ScreenWave.DURATION;}
 public void setPower(boolean target,long now){setPower(target,now,null);}
 public void setPower(boolean target,long now,net.minecraft.core.BlockPos clicked){
  if(target==power)return;
  if(!animating(now)){faultOrigin=null;faultEvent=-1;waveBase=power;waveTimes=new long[0];waveTargets=new boolean[0];clickOrigins=new net.minecraft.core.BlockPos[0];waveHeading=heading;}
  // Bound a burst of repeated requests. Normal clicks and wireless pulses are unaffected.
  if(waveTimes.length>=64)return;
  int i=waveTimes.length;waveTimes=java.util.Arrays.copyOf(waveTimes,i+1);waveTargets=java.util.Arrays.copyOf(waveTargets,i+1);
  clickOrigins=java.util.Arrays.copyOf(clickOrigins,i+1);clickOrigins[i]=clicked==null?null:clicked.immutable();
  waveTimes[i]=now;waveTargets[i]=target;power=target;
 }
 public UUID group;public int manualFaces;
 public UUID id;public long revision;public boolean power,wireless=true;public int opacity=0;
 public ItemStack first=ItemStack.EMPTY,second=ItemStack.EMPTY;
 public CabinSettings copy(){var c=new CabinSettings();c.group=group;c.manualFaces=manualFaces;c.clickOrigins=clickOrigins.clone();c.hudBrightness=hudBrightness;c.mouseLock=mouseLock;c.mouseWireless=mouseWireless;c.mouseFirst=mouseFirst.copy();c.mouseSecond=mouseSecond.copy();c.radarLink=radarLink;c.radarController=radarController;c.hudMask=hudMask;c.seamOpacity=seamOpacity;c.highlightOpacity=highlightOpacity;c.hudScale=hudScale;c.hudColor=hudColor;c.origin=origin;c.hudCenter=hudCenter;c.faultOrigin=faultOrigin;c.faultEvent=faultEvent;c.highlights=new java.util.ArrayList<>(highlights);c.heading=heading;c.waveHeading=waveHeading;c.waveBase=waveBase;c.waveTimes=waveTimes.clone();c.waveTargets=waveTargets.clone();c.id=id;c.revision=revision;c.power=power;c.wireless=wireless;c.opacity=opacity;c.first=first.copy();c.second=second.copy();return c;}
 public CompoundTag save(HolderLookup.Provider r){var t=new CompoundTag();HudCenterData.save(t,hudCenter);if(group!=null)t.putUUID("group",group);t.putInt("manualFaces",manualFaces);t.putInt("hudBrightness",hudBrightness);var starts=new net.minecraft.nbt.ListTag();for(var pos:clickOrigins){var entry=new CompoundTag();if(pos!=null)entry.putLong("pos",pos.asLong());starts.add(entry);}t.put("clickOrigins",starts);t.putBoolean("mouseLock",mouseLock);t.putBoolean("mouseWireless",mouseWireless);if(!mouseFirst.isEmpty())t.put("mouseFirst",mouseFirst.save(r));if(!mouseSecond.isEmpty())t.put("mouseSecond",mouseSecond.save(r));if(radarLink!=null)t.putLong("radarLink",radarLink.asLong());if(radarController!=null)t.putLong("radarController",radarController.asLong());t.putInt("hudMask",hudMask);t.putInt("seamOpacity",seamOpacity);t.putInt("highlightOpacity",highlightOpacity);t.putInt("hudScale",hudScale);t.putInt("hudColor",hudColor);if(origin!=null)t.putLong("origin",origin.asLong());if(faultOrigin!=null)t.putLong("faultOrigin",faultOrigin.asLong());t.putInt("faultEvent",faultEvent);var regions=new net.minecraft.nbt.ListTag();for(var region:highlights)regions.add(region.save());t.put("highlights",regions);t.putInt("heading",heading);t.putInt("waveHeading",waveHeading);t.putBoolean("waveBase",waveBase);t.putLongArray("waveTimes",waveTimes);int[] targets=new int[waveTargets.length];for(int i=0;i<targets.length;i++)targets[i]=waveTargets[i]?1:0;t.putIntArray("waveTargets",targets);if(id!=null)t.putUUID("id",id);t.putLong("revision",revision);t.putBoolean("power",power);t.putBoolean("wireless",wireless);t.putInt("opacity",opacity);if(!first.isEmpty())t.put("first",first.save(r));if(!second.isEmpty())t.put("second",second.save(r));return t;}
 public static CabinSettings load(CompoundTag t,HolderLookup.Provider r){var c=new CabinSettings();c.group=t.hasUUID("group")?t.getUUID("group"):null;c.manualFaces=t.getInt("manualFaces")&63;c.hudCenter=HudCenterData.load(t);c.hudBrightness=t.contains("hudBrightness")?Math.clamp(t.getInt("hudBrightness"),0,300):150;c.mouseLock=!t.contains("mouseLock")||t.getBoolean("mouseLock");c.mouseWireless=!t.contains("mouseWireless")||t.getBoolean("mouseWireless");c.mouseFirst=ItemStack.parseOptional(r,t.getCompound("mouseFirst"));c.mouseSecond=ItemStack.parseOptional(r,t.getCompound("mouseSecond"));c.radarLink=t.contains("radarLink")?net.minecraft.core.BlockPos.of(t.getLong("radarLink")):null;c.radarController=t.contains("radarController")?net.minecraft.core.BlockPos.of(t.getLong("radarController")):null;c.hudMask=t.contains("hudMask")?t.getInt("hudMask")&63:63;c.seamOpacity=t.contains("seamOpacity")?Math.clamp(t.getInt("seamOpacity"),0,100):5;c.highlightOpacity=t.contains("highlightOpacity")?Math.clamp(t.getInt("highlightOpacity"),0,100):100;c.hudScale=t.contains("hudScale")?Math.clamp(t.getInt("hudScale"),50,2000):500;c.hudColor=t.contains("hudColor")?t.getInt("hudColor")&0xFFFFFF:0x78FFFF;c.origin=t.contains("origin")?net.minecraft.core.BlockPos.of(t.getLong("origin")):null;c.faultOrigin=t.contains("faultOrigin")?net.minecraft.core.BlockPos.of(t.getLong("faultOrigin")):null;c.faultEvent=t.contains("faultEvent")?t.getInt("faultEvent"):-1;var list=t.getList("highlights",10);for(int i=0;i<Math.min(32,list.size());i++)c.highlights.add(HighlightRegion.load(list.getCompound(i)));c.id=t.hasUUID("id")?t.getUUID("id"):null;c.revision=t.getLong("revision");c.power=t.getBoolean("power");c.wireless=!t.contains("wireless")||t.getBoolean("wireless");c.opacity=t.contains("opacity")?Math.clamp(t.getInt("opacity"),0,100):0;c.heading=Math.floorMod(t.getInt("heading"),360);c.waveHeading=Math.floorMod(t.getInt("waveHeading"),360);c.waveBase=t.contains("waveBase")?t.getBoolean("waveBase"):c.power;c.waveTimes=t.getLongArray("waveTimes");int[] a=t.getIntArray("waveTargets");if(a.length!=c.waveTimes.length||a.length>64)c.waveTimes=new long[0];c.waveTargets=new boolean[c.waveTimes.length];for(int i=0;i<c.waveTargets.length;i++)c.waveTargets[i]=a[i]!=0;c.clickOrigins=new net.minecraft.core.BlockPos[c.waveTimes.length];var starts=t.getList("clickOrigins",10);for(int i=0;i<Math.min(starts.size(),c.clickOrigins.length);i++)if(starts.getCompound(i).contains("pos"))c.clickOrigins[i]=net.minecraft.core.BlockPos.of(starts.getCompound(i).getLong("pos"));c.first=ItemStack.parseOptional(r,t.getCompound("first"));c.second=ItemStack.parseOptional(r,t.getCompound("second"));return c;}
}
